Evaluate the JavaScript procedural FPS map generator implementation on a scale of 0-10 points:

**Map Generation Quality (4 points)**: Does it create realistic, playable FPS maps with proper room layouts, corridors, and tactical positions? Are maps varied and interesting rather than random noise?

**Connectivity & Features (3 points)**: Does it properly implement flood-fill to ensure all areas are reachable? Are spawn points and weapon pickups strategically placed?

**Performance & Interface (2 points)**: Does it generate maps efficiently at 60 FPS? Does the "Generate New Map" button work with a clear legend?

**Code Architecture (1 point)**: Is the code well-structured with proper procedural generation algorithms and error handling?

Solution A: ```javascript
function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');
    const N = 500;
    const occupancy = new Uint8Array(N * N);
    const visited = new Uint8Array(N * N);
    const roomCount = 8;
    const maxAttempts = 20;
    const roomMinSize = 70;
    const roomMaxSize = 150;
    const spawnCount = 6;
    const weaponCount = 6;

    function randomInt(min, max) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function placeRooms() {
        const rooms = [];
        let attempts = 0;
        while (rooms.length < roomCount && attempts < 1000) {
            const w = randomInt(roomMinSize, roomMaxSize);
            const h = randomInt(roomMinSize, roomMaxSize);
            const x = randomInt(0, N - w);
            const y = randomInt(0, N - h);
            let overlap = false;
            for (const r of rooms) {
                if (x < r.x + r.w && x + w > r.x && y < r.y + r.h && y + h > r.y) {
                    overlap = true;
                    break;
                }
            }
            if (!overlap) {
                rooms.push({x, y, w, h});
                for (let i = x; i < x + w; i++) {
                    for (let j = y; j < y + h; j++) {
                        occupancy[j * N + i] = 1;
                    }
                }
            }
            attempts++;
        }
        return rooms;
    }

    function connectRooms(rooms) {
        for (let i = 0; i < rooms.length - 1; i++) {
            const a = rooms[i];
            const b = rooms[i + 1];
            const ax = a.x + Math.floor(a.w / 2);
            const ay = a.y + Math.floor(a.h / 2);
            const bx = b.x + Math.floor(b.w / 2);
            const by = b.y + Math.floor(b.h / 2);
            if (randomInt(0, 1) === 0) {
                carveHorizontal(ax, bx, ay);
                carveVertical(ax, bx, ay, by);
            } else {
                carveVertical(ax, bx, ay, by);
                carveHorizontal(ax, bx, by);
            }
        }
    }

    function carveHorizontal(x1, x2, y) {
        const min = Math.min(x1, x2);
        const max = Math.max(x1, x2);
        for (let x = min; x <= max; x++) {
            occupancy[y * N + x] = 1;
        }
    }

    function carveVertical(x1, x2, y1, y2) {
        const min = Math.min(y1, y2);
        const max = Math.max(y1, y2);
        for (let y = min; y <= max; y++) {
            occupancy[y * N + x1] = 1;
        }
    }

    function floodFill(startX, startY) {
        visited.fill(0);
        const stack = [];
        stack.push(startX * N + startY);
        while (stack.length) {
            const idx = stack.pop();
            if (visited[idx]) continue;
            visited[idx] = 1;
            const x = idx % N;
            const y = Math.floor(idx / N);
            if (x > 0 && occupancy[idx - 1] && !visited[idx - 1]) stack.push(idx - 1);
            if (x < N - 1 && occupancy[idx + 1] && !visited[idx + 1]) stack.push(idx + 1);
            if (y > 0 && occupancy[idx - N] && !visited[idx - N]) stack.push(idx - N);
            if (y < N - 1 && occupancy[idx + N] && !visited[idx + N]) stack.push(idx + N);
        }
    }

    function allReachable(rooms) {
        floodFill(0, 0);
        for (const r of rooms) {
            for (let i = r.x; i < r.x + r.w; i++) {
                for (let j = r.y; j < r.y + r.h; j++) {
                    if (occupancy[j * N + i] && !visited[j * N + i]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    function placeItems(count, color) {
        const items = [];
        let attempts = 0;
        while (items.length < count && attempts < 1000) {
            const x = randomInt(0, N - 1);
            const y = randomInt(0, N - 1);
            if (occupancy[y * N + x] && !visited[y * N + x]) {
                items.push({x, y});
            }
            attempts++;
        }
        return items;
    }

    function draw() {
        ctx.fillStyle = 'black';
        ctx.clearRect(0, 0, N, N);
        // draw floor
        ctx.fillStyle = 'gray';
        for (let i = 0; i < N * N; i++) {
            if (occupancy[i]) {
                const x = i % N;
                const y = Math.floor(i / N);
                ctx.fillRect(x, y, 1, 1);
            }
        }
        // spawn points
        for (const p of spawnPoints) {
            ctx.fillStyle = 'green';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        }
        // weapon pickups
        for (const p of weaponPoints) {
            ctx.fillStyle = 'red';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        }
        // legend
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(10, N - 80, 120, 70);
        ctx.fillStyle = 'white';
        ctx.font = '12px Arial';
        ctx.fillText('Legend', 15, N - 60);
        ctx.fillStyle = 'black';
        ctx.fillRect(15, N - 45, 10, 10);
        ctx.fillStyle = 'gray';
        ctx.fillRect(15, N - 30, 10, 10);
        ctx.fillStyle = 'green';
        ctx.fillRect(15, N - 15, 10, 10);
        ctx.fillStyle = 'red';
        ctx.fillRect(15, N, 10, 10);
        ctx.fillStyle = 'white';
        ctx.fillText('Walls', 30, N - 36);
        ctx.fillText('Floors', 30, N - 21);
        ctx.fillText('Spawn', 30, N - 6);
        ctx.fillText('Weapon', 30, N + 9);
    }

    function generate() {
        let success = false;
        for (let attempt = 0; attempt < maxAttempts && !success; attempt++) {
            occupancy.fill(0);
            const rooms = placeRooms();
            connectRooms(rooms);
            if (allReachable(rooms)) {
                spawnPoints = placeItems(spawnCount, 'green');
                weaponPoints = placeItems(weaponCount, 'red');
                success = true;
            }
        }
        draw();
    }

    let spawnPoints, weaponPoints;

    // button
    const btn = document.createElement('button');
    btn.textContent = 'Generate New Map';
    btn.style.position = 'absolute';
    btn.style.left = canvas.offsetLeft + 'px';
    btn.style.top = canvas.offsetTop + canvas.height + 10 + 'px';
    btn.style.width = '150px';
    document.body.appendChild(btn);
    btn.addEventListener('click', generate);
    generate();
}
```

Solution B: function generateProceduralMap(canvasId) {
    // Constants
    const CANVAS_SIZE = 500;
    const CELL_SIZE = 10;
    const GRID_SIZE = CANVAS_SIZE / CELL_SIZE;
    const WALL = 0, FLOOR = 1;
    const ROOM_COUNT_MIN = 5, ROOM_COUNT_MAX = 9;
    const ROOM_SIZE_MIN = 4, ROOM_SIZE_MAX = 10;
    const SPAWN_COUNT = 3;
    const WEAPON_COUNT = 5;

    // Helper: create or get element
    function getOrCreate(id, tag, parent, html) {
        let el = document.getElementById(id);
        if (!el) {
            el = document.createElement(tag);
            el.id = id;
            if (html) el.innerHTML = html;
            parent.appendChild(el);
        }
        return el;
    }

    // Setup canvas
    const canvas = document.getElementById(canvasId);
    if (!canvas) throw new Error('Canvas not found');
    canvas.width = CANVAS_SIZE;
    canvas.height = CANVAS_SIZE;
    const ctx = canvas.getContext('2d');

    // UI container (legend & button)
    const container = getOrCreate(canvasId + '-container', 'div', canvas.parentNode);
    container.style.position = 'relative';
    canvas.style.display = 'block';
    canvas.style.position = 'absolute';
    canvas.style.left = '0';
    canvas.style.top = '0';

    // Legend
    const legend = getOrCreate('map-legend', 'div', container);
    legend.style.position = 'absolute';
    legend.style.right = '10px';
    legend.style.bottom = '10px';
    legend.style.background = 'rgba(255,255,255,0.8)';
    legend.style.padding = '5px';
    legend.style.font = '12px sans-serif';
    legend.innerHTML = `
        <div><span style="display:inline-block;width:12px;height:12px;background:#000;"></span> Wall</div>
        <div><span style="display:inline-block;width:12px;height:12px;background:#777;"></span> Floor</div>
        <div><span style="display:inline-block;width:12px;height:12px;background:#0f0;border-radius:50%;"></span> Spawn</div>
        <div><span style="display:inline-block;width:12px;height:12px;background:#f00;"></span> Weapon</div>
    `;

    // Generate button
    const button = getOrCreate('map-generate', 'button', container, 'Generate New Map');
    button.style.position = 'absolute';
    button.style.left = '10px';
    button.style.bottom = '10px';
    button.onclick = () => generateProceduralMap(canvasId);

    // Map data
    const map = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(WALL));
    const rooms = [];

    // Random helpers
    const rand = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
    const intersect = (a, b) => !(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);

    // Create rooms
    const roomCount = rand(ROOM_COUNT_MIN, ROOM_COUNT_MAX);
    let attempts = 0;
    while (rooms.length < roomCount && attempts < 200) {
        attempts++;
        const w = rand(ROOM_SIZE_MIN, ROOM_SIZE_MAX);
        const h = rand(ROOM_SIZE_MIN, ROOM_SIZE_MAX);
        const x = rand(1, GRID_SIZE - w - 1);
        const y = rand(1, GRID_SIZE - h - 1);
        const newRoom = { x, y, w, h, cx: x + Math.floor(w / 2), cy: y + Math.floor(h / 2) };
        if (rooms.some(r => intersect(r, newRoom))) continue;
        rooms.push(newRoom);
        for (let i = y; i < y + h; i++) {
            for (let j = x; j < x + w; j++) {
                map[i][j] = FLOOR;
            }
        }
    }

    // Connect rooms with corridors
    rooms.sort((a, b) => a.cx - b.cx);
    for (let i = 0; i < rooms.length - 1; i++) {
        const a = rooms[i], b = rooms[i + 1];
        let x = a.cx, y = a.cy;
        while (x !== b.cx) {
            map[y][x] = FLOOR;
            x += x < b.cx ? 1 : -1;
        }
        while (y !== b.cy) {
            map[y][x] = FLOOR;
            y += y < b.cy ? 1 : -1;
        }
    }

    // Flood-fill to ensure connectivity
    const reachable = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(false));
    const stack = [];
    const start = rooms[0];
    stack.push([start.cy, start.cx]);
    reachable[start.cy][start.cx] = true;
    while (stack.length) {
        const [cy, cx] = stack.pop();
        [[0,1],[1,0],[-1,0],[0,-1]].forEach(([dy,dx])=>{
            const ny = cy+dy, nx = cx+dx;
            if (ny>=0 && ny<GRID_SIZE && nx>=0 && nx<GRID_SIZE && map[ny][nx]===FLOOR && !reachable[ny][nx]) {
                reachable[ny][nx]=true;
                stack.push([ny,nx]);
            }
        });
    }
    // Connect unreachable floors
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            if (map[y][x]===FLOOR && !reachable[y][x]) {
                // find nearest reachable floor
                let found = false;
                for (let r = 1; r < GRID_SIZE && !found; r++) {
                    for (let dy = -r; dy <= r && !found; dy++) {
                        const dx = r - Math.abs(dy);
                        for (let sign of [-1,1]) {
                            const nx = x + dx*sign, ny = y + dy;
                            if (nx>=0 && nx<GRID_SIZE && ny>=0 && ny<GRID_SIZE && reachable[ny][nx]) {
                                // carve L corridor
                                let cx = x, cy = y;
                                while (cx !== nx) { map[cy][cx]=FLOOR; cx+= cx<nx?1:-1; }
                                while (cy !== ny) { map[cy][cx]=FLOOR; cy+= cy<ny?1:-1; }
                                reachable[y][x]=true;
                                found=true;
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    // Helper to pick random floor cells
    function randomFloor(exclude=[]) {
        while (true) {
            const x = rand(0, GRID_SIZE - 1);
            const y = rand(0, GRID_SIZE - 1);
            if (map[y][x] !== FLOOR) continue;
            if (exclude.some(p=>p.x===x && p.y===y)) continue;
            return { x, y };
        }
    }

    // Spawn points
    const spawns = [];
    for (let i = 0; i < SPAWN_COUNT; i++) {
        spawns.push(randomFloor(spawns));
    }

    // Weapon pickups
    const weapons = [];
    for (let i = 0; i < WEAPON_COUNT; i++) {
        weapons.push(randomFloor([...spawns, ...weapons]));
    }

    // Draw map
    ctx.clearRect(0,0,CANVAS_SIZE,CANVAS_SIZE);
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            ctx.fillStyle = map[y][x]===WALL ? '#000' : '#777';
            ctx.fillRect(x*CELL_SIZE, y*CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }
    }
    // Draw spawns
    spawns.forEach(p=>{
        ctx.fillStyle = '#0f0';
        ctx.beginPath();
        ctx.arc((p.x+0.5)*CELL_SIZE, (p.y+0.5)*CELL_SIZE, CELL_SIZE/3,0,Math.PI*2);
        ctx.fill();
    });
    // Draw weapons
    weapons.forEach(p=>{
        ctx.fillStyle = '#f00';
        ctx.fillRect(p.x*CELL_SIZE+CELL_SIZE*0.2, p.y*CELL_SIZE+CELL_SIZE*0.2, CELL_SIZE*0.6, CELL_SIZE*0.6);
    });
}

